import type { SVGProps } from 'react';

/**
 * Icon set inlined as SVG path data so consumers install no icon packages.
 *
 * Phosphor (MIT), regular weight, on Phosphor's native 256 grid. Filled
 * glyphs rather than the 24-grid strokes this set used before: a stroked
 * Lucide-style icon is the default look of every editor built on shadcn, and
 * the filled shapes read as their own thing at toolbar size while staying
 * legible at 18px.
 *
 * Generated — see the icon generator in the repo notes rather than editing
 * path data by hand.
 */

export interface IconProps extends SVGProps<SVGSVGElement> {
  size?: number;
}

function Icon({ size = 18, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 256 256"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

/**
 * The one stroke weight for every stroked icon in this set.
 *
 * Sources author these at anything from 1.5 to 2, and keeping each icon's own
 * value is what makes a toolbar look uneven — the eye reads differing stroke
 * weight as differing emphasis. 1.75 on a 24 grid at 18px is the weight that
 * sits closest to the apparent density of the filled Phosphor glyphs beside
 * them. Override it per icon only to correct a glyph that is genuinely denser
 * or sparser than the rest, never to preserve how a source file happened to
 * be drawn.
 */
const STROKE_WIDTH = 1.75;

/** Stroked icons on a 24 grid, for glyphs drawn outside the Phosphor set. */
function StrokeIcon({ size = 18, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={STROKE_WIDTH}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

/** Filled icons on a 24 grid, for the same reason as `StrokeIcon`. */
function FillIcon24({ size = 18, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

